insert into public.categories(name) values ('Sculpture');
insert into public.products(slug,name,description,category_id,sample,display_order) values ('mahalakshmi','Sri Mahalakshmi Devi','Sri Mahalakshmi Devi seated on a lotus pedestal. Compare the physical print with the digital sculpt, from the folds at its base to the detail in the crown.',(select id from public.categories where name='Sculpture'),true,1);
