insert into public.product_media(product_id,kind,path,alt,display_order,is_primary) values ((select id from public.products where slug='mahalakshmi'),'photo','/mahalakshmi-front.webp','Studio render',0,true);
insert into public.product_media(product_id,kind,path,alt,display_order,is_primary) values ((select id from public.products where slug='mahalakshmi'),'photo','/sculpture.webp','Print photo',1,false);
